insert into public.subjects (slug, name, description, icon, sort_order) values
('direito-administrativo', 'Direito Administrativo', 'Administração pública, atos administrativos e serviços públicos.', 'Briefcase', 101),
('direito-constitucional', 'Direito Constitucional', 'Constituição, direitos fundamentais e organização do Estado.', 'Scale', 102),
('direito-penal', 'Direito Penal', 'Princípios penais, teoria do crime e excludentes.', 'Gavel', 103),
('direito-civil', 'Direito Civil', 'Pessoas, contratos e responsabilidade civil.', 'BookOpen', 104),
('processo-civil', 'Processo Civil', 'Regras fundamentais do processo e tutela jurisdicional.', 'FileText', 105),
('processo-penal', 'Processo Penal', 'Investigação, ação penal e garantias processuais.', 'Gavel', 106),
('direito-do-trabalho', 'Direito do Trabalho', 'Relação de emprego, jornada e direitos trabalhistas.', 'Briefcase', 107),
('direito-tributario', 'Direito Tributário', 'Competência, tributos e obrigações tributárias.', 'FileText', 108),
